procedure TFrmMain.ActNewExecute(Sender: TObject);
var
  MtdName: string;
  Frm: TFrmInputQuery;
  B: Boolean;
begin
  if not CheckUpgradeDbMtd then
    Exit;
  Frm := TFrmInputQuery.Create(Application);
  try
    B := Frm.Input('新建方法', '输入方法名称', itMtdName, MtdName);
  finally
    Frm.Free;
  end;
  if B and CheckMtdName(MtdName) then
  begin
    if not ModifyMtd(True) then
      Exit;
    G_SdMtd.Init(MtdName);
    CallFrmMtdCfg;
    if G_SdMtd.Enabled then
      CallFrmMtdLines;
  end;
end;

procedure TFrmMain.ActOpenExecute(Sender: TObject);
var
  Frm: TFrmSelect;
  Id: Integer;
  Lay: TCcdLay;
begin
  if not CheckUpgradeDbMtd then
    Exit;
  Frm := TFrmSelect.Create(Application);
  try
    if Frm.OpenMtdDialog then
      Id := Frm.RecId
    else
      Id := G_SdMtd.MtdId;
  finally
    Frm.Free;
  end;
  if Id = 0 then
    Exit;
  try
    G_DbMtd.MtdOpen;
    try
      G_DbMtd.MtdLoadSdMtd(Id, G_SdMtd);
      Lay := TCcdLay.Create(G_SdOpts);
      if not G_SdMtd.CcdLay.IsSame(Lay) then
        ShowWarnMsg('方法中谱板设置与硬件设置不一致' + sLineBreak
          + '请确认是否需要重新设置');
      Lay.Free;
      G_SdLineSet.SetRefLine(G_SdMtd.RefWave, G_SdMtd.RealRefWave,
        G_SdMtd.RefWidth);
      G_DbMtd.MtdLinesOpen(G_SdMtd.MtdId);
      G_DbMtd.MtdLinesGetAll(G_SdLineSet);
      G_DbMtd.MtdLinesClose;
    except
      on E: Exception do
      begin
        ShowErrMsg(E.Message);
        G_SdMtd.Reset;
        G_DbMtd.MtdLinesClose;
      end;
    end;
  finally
    G_DbMtd.MtdClose;
  end;
  SetCaption;
end;

procedure TFrmMain.ActSaveAsExecute(Sender: TObject);
var
  Frm: TFrmSelect;
begin
  Frm := TFrmSelect.Create(Application); ;
  try
    if Frm.SaveMtdDialog then
    begin
      if Frm.RecId <> G_SdMtd.MtdId then
      begin
        G_SdMtd.MtdName := Frm.RecName;
        try
          G_DbMtd.MtdSaveAs(Frm.RecId, G_SdMtd, G_SdLineSet);
        except
          on E: Exception do
          begin
            ShowErrMsg(E.Message);
            Exit;
          end;
        end;
      end;
    end;
  finally
    Frm.Free;
    SetCaption;
  end;
end;

