procedure TFrmMain.ActReCalExecute(Sender: TObject);

  function LoadPdt: Boolean;
  const
    StrTimeOver = '方法已修改,计算结果可能不正确!' + sLineBreak + '继续计算吗?';
  var
    S: string;
    I, SdLineIndex: Integer;
  begin
    Result := False;
    DmRes.SetOpenDialog(ftPdt);
    if DmRes.OpenDialog.Execute then
    begin
      S := DmRes.OpenDialog.FileName;
      try
        G_SdMatrix.LoadPdt(S);
      except
        on E: Exception do
        begin
          ShowErrMsg(E.Message);
          Exit;
        end;
      end;
      if G_SdMatrix.MtdId <> G_SdMtd.MtdId then
      begin
        ShowWarnMsg('不是当前方法的' + FileDescribes[ftPdt] + '!');
        Exit;
      end;
      if G_SdMatrix.ExpSegMode <> G_SdMtd.ExpSegMode then
      begin
        S := '数据格式不匹配!' + sLineBreak + '分析方法模式:' +
        ExpSegModeNames[G_SdMtd.ExpSegMode] + sLineBreak + FileDescribes[ftPdt]
          + '格式:' + ExpSegModeNames[not G_SdMtd.ExpSegMode];
        ShowWarnMsg(S);
        Exit;
      end;
      if G_SdMatrix.LineCount <> G_SdMtdMap.LineCount then
      begin
        ShowWarnMsg(FileDescribes[ftPdt] + '的谱线数量与方法映射不一致!');
        Exit;
      end;
      for I := 1 to G_SdMatrix.LineCount - 1 do
      begin
        SdLineIndex := G_SdMtdMap.LineMaps[I].SdLineIndex;
        if (G_SdMatrix.Eles[I] <> G_SdLineSet.Lines[SdLineIndex].Ele) or
          (G_SdMatrix.Waves[I] <> G_SdLineSet.Lines[SdLineIndex].Wave) then
        begin
          S := '第' + IntToStr(I) + '谱线符号或波长与方法映射不一致!' + sLineBreak;
          with G_SdLineSet.Lines[SdLineIndex] do
            S := S + '分析方法:' + FormatEleAndWave(Ele, Wave) + sLineBreak;
          with G_SdMatrix do
            S := S + FileDescribes[ftPdt] + ':' + FormatEleAndWave(Eles[I], Waves[I]);
          ShowWarnMsg(S);
          Exit;
        end
      end;
      if G_SdMatrix.MeasureTime < G_SdMtd.ModifyTime then
      begin
        if Application.MessageBox(StrTimeOver, '重新计算',
          MB_ICONQUESTION + MB_YESNO) <> ID_YES then
          Exit;
      end;
      Result := True;
    end;
  end;

begin
  if not TryCreateSdMtdMap(G_SdMtd.ExpSegMode) then
    Exit;
  if LoadPdt then
  begin
    if DisplayFrmAnaPdt(False) then
    begin
      FHasFocus := False;
      FrmAnaCurve.Execute;
      Exit;
    end;
  end;
  FreeAndNil(G_SdMtdMap);
end;

