procedure TFrmAnaCurve.ActNextExecute(Sender: TObject);
var
//  I: Integer;
  Frm: TFrmPrintDat;
begin
//    for I := 0 to FCurver.Count - 1 do
//      G_StdLoader.CurBlack[I] := FCurver.X[I];
    G_StdLoader.SetToStds(G_SdLineSet.Lines[FSdLineIndex].Stds);
    FDatLineIterator.Next;
    if FindDatLine then
    begin
      if not CalLineCurve then
        Close;
    end
    else
    begin
      FOk := True;
      Close;
      MergeDatas;
      G_DbMtd.MtdLinesUpdateStds(G_SdMtd.MtdId, G_SdLineSet);
      if G_SdMatrix.SampCount > 0 then
      begin
        Frm := TFrmPrintDat.Create(Application);
        try
          Frm.Execute('');
        finally
          Frm.Free;
        end;
      end;
    end;
end;

