procedure TFrmAnaPdt.BtOkClick(Sender: TObject);
var
  PdtName: string;
begin
  if CbDefault.Checked then
  begin
    G_SdCfgs.IsPrintPdt := CbPrintPdt.Checked;
    G_SdCfgs.IsPrintToTxt := CbPrintToTxt.Checked;
    G_SdCfgs.IsSavePdt := CbSavePdt.Checked;
    G_SdCfgs.IsSaveWave := CbSaveWave.Checked;
    G_SdCfgs.SaveMethod;
  end;
  if CbSaveWave.Checked then
  begin
    try
      SaveAllWaves;
    except
      on E: Exception do
      begin
        ShowErrMsg(E.Message);
        Close;
        Exit;
      end;
    end;
  end;
  if CbSavePdt.Checked then
  begin
    PdtName := GetDefaultPdtName(G_SdMatrix.MeasureTime);
    DmRes.SetSaveDialog(ftPdt, '保存' + FileDescribes[ftPdt], PdtName);
    if DmRes.SaveDialog.Execute then
    begin
      PdtName := DmRes.SaveDialog.FileName;
      try
        G_SdMatrix.SavePdt(PdtName);
      except
        on E: Exception do
        begin
          ShowWarnMsg(E.Message + sLineBreak + '无法保存: ' + PdtName);
        end;
      end;
    end;
  end;
  if CbPrintPdt.Checked then
    PrintPdt;
  if CbPrintToTxt.Checked then
    PrintToTxt;
  ModalResult := mrOk;
end;

