procedure TFrmDockAwareSam.ActLoadMultiExecute(Sender: TObject);
var
  BmList: TBookmarkList;
  I: Integer;
begin
  BmList := DbgBand.SelectedRows;
  if BmList.Count < 2 then
  begin
    ShowInformationMsg('当前只选定了单个记录');
    Exit;
  end;
  if BmList.Count > MaxCcdBandVolume then
  begin
    ShowInformationMsg('当前选定记录数大于允许值: ' + IntToStr(MaxCcdBandVolume));
    Exit;
  end;
  G_CcdBandSet.Count := BmList.Count;
  DsBand.OnDataChange := nil;
  DataSet.DisableControls;
  try
    for I := 0 to BmList.Count - 1 do
    begin
      DataSet.GotoBookmark(BmList.Items[I]);
      G_DbCcd.LoadCcdBand(G_CcdBandSet.CcdBands[I]);
    end;
    G_CcdBandSet.CcdNo := G_CcdBand.CcdNo;  //LoadCcdBand后FCcdBand才Active
    G_CcdBand := G_CcdBandSet.FocusedBand;
    DataSet.EnableControls;
    G_DbCcd.SetBandOuted; //多样查看的最后一个书签记录需强制刷新
    FDbGridRow := TDBGHack(DbgBand).Row;
    FBandOuted := True;
    FMultiSelectEnable := False;
    DsBand.OnDataChange := DsBandDataChange;
//    DbgBand.OnMouseActivate := DbgBandMouseActivate;
    PostMessage(FViewForm.Handle, WM_BAND, Integer(bwBandChanged), 0);
  except
    on E: Exception do
    begin
      ErrMsg := E.Message;
      PostMessage(FViewForm.Handle, WM_BAND, Integer(bwErr), Integer(@ErrMsg));
      Exit;
    end;
  end;
end;

procedure TFrmDockGuideIgnit.BtnIgnitClick(Sender: TObject);
{$IFDEF ACQ_MOCK}
  procedure StartMock(const FillDark: WORD);
  var
    I: Integer;
    CcdCyc: TCcdCyc;
  begin
    with G_AcqThread do
    begin
      if PreBurnNum < MinPreNum then
        I := MinPreNum
      else
        I := PreBurnNum;
      I := I + BurnCycNum * BurnCount;
      if DarkCycNum * DarkCount > 0 then
      begin
        I := I + 4; // 转换1s
      end;
      I := I + DarkCycNum * DarkCount + 2; // 读数0.5S
      TmMock.Interval := Time250ms * I;
      TmMock.Enabled := True;
    end;
    for I := 0 to G_CcdBand.CcdCycSet.BurnCycList.Count - 1 do
    begin
      CcdCyc := G_CcdBand.CcdCycSet.BurnItems[I];
      G_CcdBand.Acq2Ccd(AcqCycMock, CcdCyc);
    end;
    for I := 0 to G_CcdBand.CcdCycSet.DarkCycList.Count - 1 do
    begin
      CcdCyc := G_CcdBand.CcdCycSet.DarkItems[I];
      CcdCyc.Fill(FillDark);
    end;
  end;
{$ENDIF }

var
  BandName, S: string;
begin
  if G_DbCcd.RecordCount >= MaxSampSize then
  begin
    ShowInformationMsg('谱带数量已到限制值:' + IntToStr(MaxSampSize));
    Exit;
  end;
  FHeatIgnit := (Sender = BtnIgnitHeat);
  if FHeatIgnit then
    G_CcdBand.BandId := -1;
  if IsSamFileType(FSdFileType) then
  begin
    if FLockBtnIgnit then
      ClipCursor(nil);
    if FHeatIgnit then
    begin
      G_CcdBand.SampNo := -2;
      G_CcdBand.SampName := '预热样品'
    end
    else
    begin
      if CbNames.ItemIndex = -1 then
        G_CcdBand.SampNo := -1
      else
      if CbNames.Text = '' then
        G_CcdBand.SampNo := 0
      else
        G_CcdBand.SampNo := FAnaNo;
      G_CcdBand.SampName := CbNames.Text;
    end;
  end
  else
  begin
    if FHeatIgnit then
    begin
      BandName := '预热样品';
    end
    else
    begin
      BandName := Trim(EdtBandname.Text);
      if BandName <> '' then
      begin
        S := CheckNameValid(BandName, MaxRecordNameLength);
        if S <> '' then
        begin
          ShowWarnMsg('谱带名称' + S);
          Exit;
        end;
      end;
      EdtBandname.Text := '';
    end;
    G_CcdBand.BandName := BandName;
  end;
{$IFDEF ACQ_MOCK}
  if LoadMockAcq = False then
    Exit;
{$ELSE}
  if G_SioLinkCom.Active = False then
  begin
    try
      G_SioLinkCom.Open;
    except
      on E: Exception do
      begin
        ShowErrMsg(E.Message);
        Exit;
      end;
    end;
  end;
{$ENDIF}
  G_AcqThread.SetObsHandle(Handle);
  G_AcqThread.SdFileType := FSdFileType;
  G_AcqThread.SetIgnitCon(G_CcdBand.IgnitCon);
  PostMessage(FViewForm.Handle, WM_BAND, Integer(bwIgnitStart), 0);
  if G_SdOpts.IsLogCmd then
    FrmMessage.ClearCmdMessage;
  SetBtns(True);
  FBurnIndex := 0;
  FDarkIndex := 0;
  if IsSamFileType(FSdFileType) then
  begin
    S := G_CcdBand.SampName;
    if not FHeatIgnit then
      S := S + '  第' + IntToStr(FRepNo + 1) + '次摄谱';
  end
  else
    S := G_CcdBand.BandName;
  FFrmIgnitProgress.Display(S);
  if not IsSamFileType(FSdFileType) then
    EdtBandname.SetFocus;
{$IFDEF ACQ_MOCK}
  G_CcdBand.HasChild := True;
  StartMock(G_AcqThread.DarkCycNum * G_AcqThread.DarkCount);
{$ELSE}
  SetEvent(G_EventStartAcq);
{$ENDIF}
end;

