procedure TFrmIgnitCon.BtnOkClick(Sender: TObject);
var
  S: string;
  B: Boolean;
begin
  S := Trim(EdtName.Text);
  if S = '' then
  begin
    ShowWarnMsg(LbName.Caption + '不能为空!');
    Modalresult := mrNone;
  end;
  B := TPath.HasValidFileNameChars(S, False);
  if B = False then
  begin
    ShowWarnMsg('含有非法的文件字符!');
    Modalresult := mrNone;
  end;
  FFileName := GetDefaultDatPath + S + FileExts[FSdFileType];
  if FileExists(FFileName) then
  begin
    B := Application.MessageBox(PChar(S + StrAlreadyExist + sLineBreak + StrAskReplace),
        PChar('创建' + FStrFileType), MB_ICONQUESTION + MB_YESNO) = ID_YES;
    if B then
    begin
      try
       TFile.Delete(FFileName);
      except
        on E: Exception do
        begin
          ShowErrMsg('删除旧文件时出错!');
          ModalResult := mrNone;
        end;
      end;
    end else
      ModalResult := mrNone;
  end;
  TFile.Copy(FullExePath + 'blk' + FileExts[FSdFileType] + '_', FFileName);
  with FIgnitCon do
  begin
    PreBurn := StrToFloat(EdtPreBurn.Text);
    BurnCyc := StrToFloat(EdtBurnCyc.Text);
    DarkCyc := BurnCyc;
    BurnCount := StrToInt(EdtBurnCount.Text);
    DarkCount := StrToInt(EdtDarkCount.Text);
    if DarkCount = 0 then
    begin
      DarkCyc := 0;
      DarkCount := 0;
    end;
  end;
  if CbSave.Checked then
    SaveIgnitcon;
end;

procedure TFrmPrintCcd.BtnPrintClick(Sender: TObject);
var
  Ori: TPrinterOrientation;
  W: Integer;
  S: string;
  MinAvg: Single;
  Cp: TCcdPoint;
begin
  if (CbIenBlack.Checked or CbIenCurve.Checked) = False then
  begin
    ShowWarnMsg(CbIenBlack.Caption + '或' + CbIenCurve.Caption + sLineBreak +
      '至少要选择一项!');
    Exit;
  end;
  if ((GetDeviceCaps(Printer.Handle, VERTSIZE) < 100)
    or (GetDeviceCaps(Printer.Handle, HORZSIZE) < 100)) then
  begin
    ShowWarnMsg('纸张窄边不能小于10厘米!');
    Exit;
  end;
  if (RbBmpView.Checked) then
  begin
    if RbPage10CCD.Checked and (FRightIndex < FLeftIndex + 512 - 1) then
    begin
      ShowWarnMsg(RbPage10CCD.Caption + '打印,像素点数不能小于512!');
      Exit;
    end;
  end
  else begin
    FLeftIndex := 0;
    FRightIndex := G_CcdBand.PointsPerCcd - 1;
  end;
  Ori := Printer.Orientation;
  CalGraphicWidth;
  try
    if FRotate then
    begin
      if(Ori = poPortrait) then
        Printer.Orientation := poLandscape
      else
        Printer.Orientation := poPortrait;
    end;
    FPPY := GetDeviceCaps(Printer.Handle, LOGPIXELSY);
    FLeftMargin := (Printer.PageWidth - FGraphicWidth) div 2;
    Printer.Title := FBandSimpleTitle;
    Printer.BeginDoc;
    CalPageTop;
    SetTitleFont;
    W := Printer.Canvas.TextWidth(Printer.Title);
    Printer.Canvas.TextOut
      (FLeftMargin + (FGraphicWidth - W) div 2, FYPos , Printer.Title);
    FYPos := FYPos + Printer.Canvas.TextHeight(Printer.Title) + Round(FPPY /InchToMm); //空1mm
    G_CcdBand.GetMinMaxAvg(MinAvg, FMaxAvg);
    if FMaxAvg < DefaultMaxAvg then FMaxAvg := DefaultMaxAvg;
    if(CbIenBlack.Checked) then
    begin
      PrintBlack;
      FYPos := FYPos + FPPY + Round(FPPY / InchToMm); //空1mm
    end;
    SetIndexFont;
    S := IntToStr(FLeftIndex + 1);
    if G_CcdBand.CcdLay.WsCof.Enabled then
    begin
      Cp := CcdPoint(G_CcdBand.CcdIndex, FLeftIndex);
      S := S + PointToAbsoluteWaveString(Cp);
    end;
    Printer.Canvas.TextOut(FLeftMargin, FYPos, S);
    S := IntToStr(FRightIndex + 1);
    if G_CcdBand.CcdLay.WsCof.Enabled then
    begin
      Cp := CcdPoint(G_CcdBand.CcdIndex, FRightIndex);
      S := S + PointToAbsoluteWaveString(Cp);
    end;
    W := Printer.Canvas.TextWidth(S);
    Printer.Canvas.TextOut(FLeftMargin + FGraphicWidth - W, FYPos, S);
    FYPos := FYPos + Printer.Canvas.TextHeight(IntToStr(FLeftIndex + 1))
      + Round(FPPY / InchToMm); //空1mm
    if CbIenCurve.Checked then
      PrintCurver;
    Printer.EndDoc;
  finally
    Printer.Orientation := Ori;
  end;
end;

procedure TFrmSampInput.ActOkExecute(Sender: TObject);
var
  I, StdIndex: Integer;
  S: string;
begin
  if FSampList.AnaCount = 0 then
  begin
    ShowWarnMsg('测量样品数量为零!');
    Exit;
  end;
  if FInputMode = imPre then
  begin
    if SaveSamps then
      ModalResult := mrOk
    else
      EdtName.SetFocus;
  end
  else if FInputMode = imAna then
  begin
    G_StdLoader.Clear;
    for I := 0 to FSampList.SampCount - 1 do
    begin
      S := FSampList.Samps[I];
      StdIndex := IndexOfStdNames(S);
      if StdIndex <> -1 then
      begin
        if not G_StdLoader.Selected[StdIndex] then
          G_StdLoader.Select(StdIndex)
        else begin
          ShowWarnMsg('同名标准:[' + S + ']已存在!');
          MoveToCell(I);
          Exit;
        end;
      end;
    end;
    for I := 1 to G_SdLineSet.LineCount - 1 do
    begin
      if G_SdLineSet.Lines[I].LineType = ltAna then
      begin
        G_StdLoader.CalStdCount(G_SdLineSet.Lines[I].Stds);
        if G_StdLoader.ActiveCount < MinStdSize then
        begin
          S := FormatEleAndWave(G_SdLineSet.Lines[I].Ele,
            G_SdLineSet.Lines[I].Wave);
          ShowWarnMsg(S + ' 有效标准点数小于 ' + IntToStr(MinStdSize));
          EdtName.SetFocus;
          Exit;
        end;
      end;
    end;
    ModalResult := mrOk;
  end
  else
    ModalResult := mrOk;
end;

