procedure TFrmSampInput.ActOpenExecute(Sender: TObject);
var
  OldSampCount: Integer;
  I, C, R: Integer;
begin
  OldSampCount := FSampList.SampCount;
  DmRes.SetOpenDialog(ftSam);
  if DmRes.OpenDialog.Execute then
  begin
    try
      FSampList.LoadFromFile(DmRes.OpenDialog.FileName);
    except
      on E: Exception do
      begin
        ShowErrMsg(E.Message + sLineBreak + '无法打开' + FileDescribes[ftSam]);
        Exit;
      end;
    end;
  end;
  if FSampList.BandCount >  FSampList.BandVolume then
  begin
    ShowInformationMsg('谱带数量大于限制值:' + IntToStr(FSampList.BandVolume)
      + sLinebreak + '程序将删除部分样号');
  end;
  while FSampList.BandCount > FSampList.BandVolume do
    FSampList.Delete(FSampList.SampCount - 1);
  if FSampList.SampCount < OldSampCount then
  begin
    for I := FSampList.SampCount to OldSampCount - 1 do
    begin
      IndexToColRow(I, C, R);
      SgSamp.Cells[C, R] := '';
    end;
  end;
  ChangeOldStdName;
  DisplaySamps;
  SetStatus;
  EdtName.SetFocus;
end;

