procedure TFrmViewSingle.ActStartExecute(Sender: TObject);
var
  S: string;
begin
  try
    AnaLineSetPointsToRealWaves;
  except
    on E: ExCeption do
    begin
      ShowWarnMsg(E.Message);
      Exit;
    end;
  end;
  StartSdMatrix;
  FBmpOk := False;
  FRunning := True;
  FFrmDockAware.DisableBrowse;
  (FFrmDockAWare as TFrmDockAwareSam).Running := True;
  ActStart.Enabled := False;
  TbStart.Action := ActRun;
  BorderIcons := BorderIcons - [biSystemMenu];
//  if G_SdCfgs.IsLogAna then
  if G_CmtBandObs.IsSave then
    G_CmtBandObs.FileName :=
      ChangeFileExt(G_DbCcd.FileName, FileExts[ftXls], '_SP');
  G_CmtBandObs.BeginObserve;
  FrmMessage.ClearAnaMessage;
  if G_SdCfgs.IsLogAna then
  begin
    if G_CmtBandObs.IsSave then
     S := StrExportCmt
    else
      S := '测量';
    S := S + '开始: '+ SysUtils.DateTimeToStr(Now);
    FrmMessage.LoginAna(S, True);
  end;
  if G_SdCfgs.IsLookBand then
  begin
    ActCross.Execute;
    ActPause.Enabled := True;
    ActStop.Enabled := True;
    TbExit.Action := ActStop;
  end
  else
  begin
    FFrmAnaProgress := TFrmAnaProgress.Create(self);
    FFrmAnaProgress.Show;
  end;
  FBandIndex := G_DbCcd.RecNo - 1;
  G_AnaThread.BandIndexMark := FBandIndex;
  G_AnaThread.BandCount := G_DbCcd.RecordCount;
  G_AnaThread.StartCmd(ctAnaSamps, 0);
end;

