procedure TFrmViewSingle.ActRunExecute(Sender: TObject);
begin
  Assert(FPause = True);
  FPause := False;
  ActCross.Execute;
  ActRun.Enabled := False;
  ActRun.ShortCut := 0;
  ActPause.Enabled := True;
