procedure TFrmMtdCfg.ActOkExecute(Sender: TObject);
var
  S: string;
  W: Single;
begin
  S := CheckRefWaveValid;
  if S <> '' then
  begin
    ShowWarnMsg(S);
    EdtRefWave.SetFocus;
    Exit;
  end;
  if Modified then
  begin
    with G_SdMtd do
    begin
      if FPrimModified or FBurnModified then
        ModifyTime := Now;
      if FBurnModified then
      begin
        IgnitCon.PreBurn := StrToFloat(EdtPreBurn.Text);
        IgnitCon.BurnCyc := StrToFloat(EdtBurnCyc.Text);
        IgnitCon.BurnCount := StrToInt(EdtBurnCount.Text);
        IgnitCon.DarkCount := StrToInt(EdtDarkCount.Text);
        if IgnitCon.DarkCount = 0  then
          IgnitCon.DarkCyc := 0
        else
          IgnitCon.DarkCyc := IgnitCon.BurnCyc;
      end;
      if FPrimModified then
      begin
        W := StrToFloat(EdtRefWave.Text);
        if W <> RefWave then
        begin
          RefWave := W;
          RealRefWave := W;
        end;
        RefWidth := StrToInt(EdtRefWidth.Text);
        MtdUnit := CbMtdUnit.Text;
        RepOfSam := StrToInt(LeSam.Text);
        RepOfStd := StrToInt(LeStd.Text);
        RepOfDiag := StrToInt(LeDiag.Text);
        LimitIda := StrToInt(LeLimitIda.Text);
        CheckRsd := CbRsd.Checked;
        LimitRsd := StrToFloat(LeLimitRsd.Text);
        ExpSegMode := CbExpSegMode.Checked;
      end;
      if FWstcModified then
      begin
        CcdLay := self.FCcdLay;
        WsName := self.FWsName;
        WsModifyTime := self.FWsModifyTime;
      end;
      if FPrimModified then
        G_DbMtd.MtdPrimPost(G_SdMtd);
      if not G_SdMtd.Enabled then
      begin
        G_SdMtd.MtdId := G_DbMtd.GetMtdId;
        G_DbMtd.MtdBurnInsert(G_SdMtd);
        G_DbMtd.MtdWstcInsert(G_SdMtd);
      end else
      begin
        if FBurnModified then
          G_DbMtd.MtdBurnUpdate(G_SdMtd);
        if FWstcModified then
          G_DbMtd.MtdWstcUpdate(G_SdMtd);
      end;
    end;
    ModalResult := mrOk;
  end;
  Close;
end;

