procedure TFrmMtdLines.ActOkExecute(Sender: TObject);
  function FindSameContent: Boolean;
  var
    I, N: Integer;
    D: Single;
  begin
    with FSdLine.Stds do
      for I := 0 to MaxStdSize - 1 do
      begin
        if Items[I].Content > 0 then
        begin
          D := Items[I].Content;
          for N := I + 1 to MaxStdSize - 1 do
            if D = Items[N].Content then
              Exit(True);
        end;
      end;
    Result := False;
  end;

  procedure ChkExpSeg;
  var
    Seg: TExpSeg;
  begin
    Seg := Txt2ExpSeg;
    if Seg = FMtdExpSeg then
      FSdLine.ExpSeg.Clear  //[0-0]默认全区间曝光
    else if Seg.IsSubOf(FMtdExpSeg) and (Seg.Range >= MinSegBurnCount) then
      FSdLine.ExpSeg := Seg
    else
      FSdLine.ExpSeg.Clear;
  end;

var
  I, N: Integer;
  D: Single;
begin
  if FDataModified then
  begin
    AckBack;
    if FLineType = ltAna then
    begin
      N := 0;
      with FSdLine.Stds do
      begin
        for I := 0 to MaxStdSize - 1 do
        begin
          D := CellToContent(I);
          if D > 0 then
            Inc(N);
          if not IsSameContent(D, Items[I].Content) then
          begin
            Items[I].ClearBlack;
            Items[I].Content := D;
          end;
        end;
        if N < MinStdSize then
        begin
          ShowWarnMsg('标准数量小于:' + IntToStr(MinStdSize));
          Exit;
        end;
        if FindSameContent then
        begin
          ShowWarnMsg('标准含量不能相同!');
          Exit;
        end;
      end;
    end;
    if Assigned(EdtRealWave.OnExit) then
      AckRealWave;
    AckSeekWidth;  //    AckPeakWidth;
    AckLowPeak;
    AckLowRatio;
    AckDigit;
    FModified := True;
    FSdLine.LineType := FLineType;
    if FSdLine.LineType = ltAna  then
    begin
      Assert(CbInterWave.ItemIndex <> -1);
      FSdLine.InterWave := FInterWaves[CbInterWave.ItemIndex];
      Assert(CbAlignWave.ItemIndex <> -1);
      FSdLine.AlignWave := FAlignWaves[CbAlignWave.ItemIndex];
    end
    else begin
      FSdLine.InterWave := 0;
      FSdLine.AlignWave := 0;
//      if FSdLine.LineType = ltAlign then
//        EdtBack.Text := '0';
    end;
    FSdLine.SeekWidth := StrToInt(EdtSeekWidth.Text);
    FSdLine.Back := StrToInt(EdtBack.Text);
    FSdLine.PeakMode := TPeakMode(CbPeakMode.ItemIndex);
    FSdLine.PeakWidth := StrToInt(EdtPeakWidth.Text);
    FSdLine.LowPeak := StrToInt(EdtLowPeak.Text);
    FSdLine.LowRatio := StrToFloat(EdtLowRatio.Text);
    FSdLine.FitMode := TFitMode(CbFitMode.ItemIndex);
    FSdLine.Digit := StrToInt(EdtDigit.Text);
    if CbLnCoord.Checked then
      FSdLine.CoordType := 1
    else
      FSdLine.CoordType := 0;
    if FSdLine.Back = 0 then
    begin
      if FSdLine.InterWave = BackInterWave then
      begin
        ShowWarnMsg(StrBackInterMark  + '必须设置背景!');
        Exit;
      end;
      if FSdLine.LineType = ltInter then
      begin
        ShowInformationMsg('请注意内标线一般要扣背景!');
      end;
    end;
    if G_SdMtd.ExpSegMode then
      ChkExpSeg;
  end;
//  if DsLines.State = dsInsert then
//    FRebuildLines := True;
  try
    G_DbMtd.MtdLinesPost(FSdLine);
  except
    on E: Exception do
    begin
      DsLines.Enabled := False;
      ShowErrMsg(E.Message);
      ModalResult := mrAbort;
      Exit;
    end;
  end;
  if PnlLines.Enabled then
    DbgLines.SetFocus;
end;

