procedure TFrmImportPre.BtnInClick(Sender: TObject);
begin
  DmRes.SetOpenDialog(ftEdt);
  if DmRes.OpenDialog.Execute then
  begin
    EdtIn.Clear;
    DsIn.Enabled := False;
    if not Assigned(FDbCcdIn) then
      FDbCcdIn := TDbCcdCyc.Create
    else
      FDbCcdIn.Close;
    FDbCcdIn.FileName := DmRes.OpenDialog.FileName;
    try
      FDbCcdIn.Open;
      FDbCcdIn.OpenLay;
      if Assigned(FCcdLay) then
        FreeAndNil(FCcdLay);
      FCcdLay := FDbCcdIn.CreateCcdLay;
      if not FCcdLay.IsSame(G_SdMtd.CcdLay) then
      begin
        ShowWarnMsg('蒸发文件的谱板参数与方法不一致!');
        CloseFreeObjs;
        Exit;
      end;
      FCcdLay.WsCof := G_SdMtd.CcdLay.Wscof;
      if Assigned(FIgnitCon) then
        FreeAndNil(FIgnitCon);
      FIgnitCon := FDbCcdIn.CreateIgnitCon;
      FDbCcdIn.CloseLay;
      FDbCcdIn.OpenBand;
    except
      on E: Exception do
      begin
        ShowWarnMsg(E.Message);
        CloseFreeObjs;
        Exit;
      end;
    end;
    if Assigned(FCcdBand) then
      FreeAndNil(FCcdBand);
    FCcdBand := TCcdBand.Create(FCcdLay, FIgnitCon);
    DsIn.DataSet := FDbCcdIn.AdsCcdBand;
    DsIn.Enabled := True;
    EdtIn.Text := FDbCcdIn.FileName;
    FMaxExpSeg.L := 1;
    FMaxExpSeg.R := FIgnitCon.BurnCount;
    SetExpSeg(FMaxExpSeg);
  end;
end;

procedure TFrmImportPre.BtnOutClick(Sender: TObject);
begin
  DmRes.SetSaveDialog(FOutType, '导出' + FileDescribes[FOutType],
    G_SdMtd.MtdName + TimeToPreStamp(Now));
  DmRes.SaveDialog.Options := DmRes.SaveDialog.Options - [ofOverwritePrompt];
  if DmRes.SaveDialog.Execute then
  begin
    EdtOut.Text := Trim(DmRes.SaveDialog.FileName);
