  DmRes.SaveDialog.Options := DmRes.SaveDialog.Options + [ofOverwritePrompt];
end;

procedure TFrmImportPre.BtnSelAllClick(Sender: TObject);
var
  DataSet: TDataSet;
  Bm: TBookmark;
  I: Integer;
begin
	DataSet := DsIn.DataSet;
	DataSet.DisableControls;
	Bm := DataSet.GetBookmark();
