procedure TFrmImportPre.BtnImportClick(Sender: TObject);
var
  BmList: TBookmarkList;
  I: Integer;
  FrmHint: TFrmHint;
begin
  if EdtIn.Text = '' then
  begin
    ShowInformationMsg('未选择' + LblIn.Caption);
    Exit;
  end;
  if EdtOut.Text = '' then
  begin
    ShowInformationMsg('未选择' + LblOut.Caption);
    Exit;
  end;
  if FOutType = ftCmt then
  begin
    if FExpSeg.Range < G_SdMtd.IgnitCon.BurnCount then
    begin
      ShowWarnMsg('蒸发文件取样区间:' + IntToStr(FExpSeg.Range)
        + '小于方法采样次数:' + IntToStr(G_SdMtd.IgnitCon.BurnCount));
      Exit;
    end;
  end;
  if DbgIn.SelectedRows.Count = 0 then
  begin
    ShowWarnMsg('未选择导入记录!');
    Exit;
  end;
  try
    if FileExists(EdtOut.Text) then
    begin
      if Application.MessageBox
        (Pchar(EdtOut.Text + StrAlreadyExist + sLineBreak + StrAskReplace),
           '', MB_ICONQUESTION + MB_YESNO) = ID_YES then
        begin
          CloseFreeDbCcdOut;
          TFile.Delete(EdtOut.Text);
        end;
    end;
    if not FileExists(EdtOut.Text) then
    begin
      DsOut.DataSet := nil;
      DbgOut.Refresh;
      TFile.Copy(FullExePath + 'blk' + FileExts[FOutType] + '_', EdtOut.Text);
    end;
    CloseFreeDbCcdOut;
    if FOutType = ftCdt then
      FDbCcdOut := TDbCcdCdt.Create
    else
      FDbCcdOut := TDbCcdCmt.Create;
    FDbCcdOut.FileName := EdtOut.Text;
    FDbCcdOut.Open;
  except
    on E: Exception do
    begin
      EdtOut.Clear;
      ShowWarnMsg(E.Message);
      CloseFreeObjs;
      Exit;
    end;
  end;
  try
    FDbCcdOut.OpenLay;
    if FDbCcdOut.LayCount = 0 then
    begin
      if CbMtdId.Checked then
        FDbCcdIn.MtdId := G_SdMtd.MtdId;
      FDbCcdOut.MtdId := FDbCcdIn.MtdId;
      FDbCcdOut.SetCcdLay(FCcdBand.CcdLay);
      FDbCcdOut.SetRefWave(G_SdMtd.RefWave);
      if FOutType = ftCmt then
      begin
        FIgnitCon.BurnCount := FExpSeg.Range;
        FDbCcdOut.SetIgnitcon(FIgnitCon);
      end;
      FDbCcdOut.PostLay;
    end
    else
    begin
      FIgnitCon.BurnCount := FExpSeg.Range;
      if not ChkExistFileLayOut then
      begin
        FDbCcdOut.Close;
        Exit;
      end;
    end;
    FDbCcdOut.CloseLay;
  except
    on E: Exception do
    begin
      ShowWarnMsg(E.Message);
      CloseFreeDbCcdOut;
      Exit;
    end;
  end;
  FDbCcdOut.OpenBand;
  DsOut.DataSet := FDbCcdOut.AdsCcdBand;
  FrmHint := TFrmHint.Create(nil);
  FrmHint.Display('正在导入蒸发文件记录,可能需等待几十秒', False);
  try
    DsIn.DataSet.DisableControls;
//    DsOut.DataSet.DisableControls;
    BmList := DbgIn.SelectedRows;
    try
      for I := 0 to BmList.Count - 1 do
      begin
        DsIn.DataSet.GotoBookmark(BmList.Items[I]);
        FDbCcdIn.LoadCcdBand(FCcdBand);
{$IFDEF DEBUG}
        if FCcdBand.ErrIndex <> 0 then   //人工设置ErrIndex
        begin
          FCcdBand.FillErrCcdCyc;
        end;
{$ENDIF}
        FDbCcdOut.TransCcdBand(FCcdBand, FExpSeg);
      end;
      DsOut.Enabled := True;
      FDbCcdOut.RefreshBand;
    finally
//      DsOut.DataSet.EnableControls;
      DsIn.DataSet.EnableControls;
      FrmHint.Close;
      FrmHint.Free;
    end;
  except
    on E: Exception do
    begin
      ShowWarnMsg(E.Message);
      FDbCcdOut.Close;
    end;
  end;
end;

procedure TFrmImportPre.BtnSetLayClick(Sender: TObject);

begin
  if DsIn.State = dsInactive then
